 async function refreshStatus(){if(!host.contains(content)||statusLoading)return;statusLoading=true;try{status=await api('manage/status');if(!host.contains(content))return;void refreshHealth();releaseHistoryTable.set(status.releaseHistory||[]);const fh=status.feedHealth;recoveryDetails.replaceChildren(line('Feed status: '+(fh?.status||'waiting')+' · Last successful feed: '+(fh?.lastFeedSuccess?new Date(fh.lastFeedSuccess).toLocaleString():'not yet recorded')+(fh?.nextRetry?' · Retry: '+new Date(fh.nextRetry).toLocaleString():'')),...(fh?.error?[line(fh.error)]:[]),...(status.catalogueReview?.reasons||[]).map(x=>line('Catalogue held: '+x)),...(fh?.quarantined||[]).map(x=>line('Quarantined entry '+x.identity+': '+x.reason)),...(status.restartSummary?[line('Restart recovery · '+status.restartSummary.pendingGrabs+' grab requests · '+status.restartSummary.imports+' import/review entries · '+status.restartSummary.recoveryJournals+' journals · '+status.restartSummary.checksums+' checksum records retained')]:[]));if(status.catalogue){const c=status.catalogue;catalogueDetails.replaceChildren(line(`Persistent catalogue · ${c.episodes} episode mappings · ${c.releases} release records`),line(`Official sync: ${c.lastSync?new Date(c.lastSync.time).toLocaleString()+' · '+c.lastSync.url:'Waiting; saved fallback available'}`),...(c.conflicts||[]).map(x=>line(x)),...(status.feedWarning?[line('Feed unavailable; page/catalogue fallback in use: '+status.feedWarning)]:[]),...(status.officialError?[line('Official source unavailable: '+status.officialError)]:[]));}const revision=JSON.stringify([status.activity?.[0],status.activity?.at(-1),status.activity?.length,status.metadataUpdated,status.profile,status.bulk,status.job]);if(revision!==lastRevision||Date.now()-lastLibraryRefresh>=30000){await loadLibrary(true);lastRevision=revision}if(current==='Downloads')await refreshFeed();document.getElementById('automationState').textContent=status.downloadsStopped?'Downloads stopped':status.workerError?'Automation blocked':status.automation?(status.feedHealth&&status.feedHealth.status!=='healthy'?'Automation running · feed needs attention':'Automation running'):'Automation paused';document.getElementById('automationToggle').textContent=status.automation?'Pause Automation':'Start Automation';document.getElementById('automationToggle').className=status.automation?'secondary':'primary';document.getElementById('automationDetail').textContent=status.workerError?'Needs attention: '+status.workerError:status.workerBusy?'Processing files':status.bulkBusy?'Verifying changed library files':`Files checked: ${status.lastCheck?new Date(status.lastCheck).toLocaleTimeString():'waiting'} · New releases: ${status.feedHealth?.nextRetry?'retry '+new Date(status.feedHealth.nextRetry).toLocaleTimeString():status.nextDiscoveryCheck?new Date(status.nextDiscoveryCheck).toLocaleString():'next cycle'}`;const job=status.job||status.bulk;const summary=job?.status==='running'?`Verifying ${job.done||0}/${job.total||0} files · ${job.path||''}`:job?.status==='complete'?`${job.total||job.done||0} files verified · saved across restarts${job.failed?' · '+job.failed+' errors':''}`:job?.status==='complete-with-errors'?`Verification finished · ${job.failed} files need attention`:job?.status==='failed'?'Verification error: '+(job.error||'Check Activity'):'Saved checksum records are reused automatically.';const missing=libraryRows.filter(x=>x.status==='missing').length,decisions=libraryRows.filter(x=>x.present&&(!x.verification||!['current','manual-import'].includes(x.status)||!x.media||x.media.height<status.profile.minimumQuality)).length;overviewJob.textContent=summary+(libraryRows.length?' · '+(!missing&&!decisions?'Library complete for your profile':missing+' missing · '+decisions+' verification / upgrade decisions'):'');cards.replaceChildren();for(const [label,value] of [['Installed',libraryRows.filter(x=>x.present).length||'—'],['Missing',libraryRows.filter(x=>x.status==='missing').length],['Verified',libraryRows.filter(x=>x.present&&x.verification).length],['Download slots',status.profile.maxConcurrentDownloads]]){const card=document.createElement('div');card.className='metric-card';const n=document.createElement('strong');n.textContent=value;card.append(n,line(label));cards.append(card)}workPreview.textContent='Upcoming work · '+Object.entries(status.workSummary?.grabs||{}).map(([k,n])=>n+' '+k.replaceAll('-',' ')).join(' · ')+(Object.keys(status.workSummary?.grabs||{}).length?'':'No pending grabs')+' · Import queue: '+(Object.entries(status.workSummary?.imports||{}).map(([k,n])=>n+' '+k.replaceAll('-',' ')).join(' · ')||'clear');renderActivity();lastRunning=job?.status==='running';}catch(e){notice(e.message)}finally{statusLoading=false;clearTimeout(pollTimer);if(host.contains(content))pollTimer=setTimeout(refreshStatus,5000)}}
 const results=await Promise.allSettled([api('settings'),api('manage/status'),api('credentials')]);if(results[0].status==='fulfilled'){config=results[0].value.settings||{};selectedLibraries=config.selectedLibraryIds||[];for(const [key,value] of Object.entries(config)){const el=form.elements.namedItem(key);if(el){if(key==='delugeLabel'&&value&&!Array.from(el.options).some(o=>o.value===value))el.add(new Option(value+' (saved; verify)',value));el.value=value}}}if(results[1].status==='fulfilled'){status=results[1].value;for(const [name,value] of Object.entries(status.profile||{})){const input=profileForm.elements.namedItem(name);if(input)input.type==='checkbox'?input.checked=value:input.value=value}}await refreshSecrets();navigate('Overview');await loadLibrary();
